program='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y,x))
            def bounds(points):
                ys = [p[0] for p in points]; xs = [p[1] for p in points]
                return (max(ys)-min(ys)+1)*(max(xs)-min(xs)+1)
            layers = sorted(colors, key=lambda color: bounds(colors[color]), reverse=True)
            replacement = dict(zip(layers, reversed(layers)))
            for y, x in cells:
                result[y][x] = replacement[grid[y][x]]
    return result
'''
